
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_r2scanl_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_r2scanl", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.650590957728654e-02, -2.645852320015180e-02, -2.638826645508699e-02, -2.628271629166642e-02, -2.612113047253102e-02, -2.586713556471736e-02, -2.547680370525102e-02, -2.535465691906379e-02, -2.465651841730966e-02, -2.463918694532186e-02, -3.069606436386269e-02, -4.711363463476664e-02, -2.868181691739289e-02, -2.475103624064127e-02, -2.021166800603686e-02, -1.481919104162753e-02, -7.771329360957428e-03, -2.693287819477028e-03, -4.798174181732483e-04, -1.885969145887986e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


